        return -1; // 分配失败
    }
    ctx->buffer_size = expected_size;

    return 0;
}

// 模拟数据解压过程
int decompress_data(const unsigned char *compressed_data, size_t data_size, struct compression_context *ctx) {
    if (!ctx->temp_buffer) {
        return -1; // 缓冲区未分配
    }

